seqs <- getSeq(FaFile("reference.fa"),GenomicRanges::GRanges(ranges$chromosome,IRanges::IRanges(ranges$start,ranges$end)))
eval(parse(text=unlist(gc_control$profiles[["1.34.1"]]$formula)))
